CREATE POLICY "Read salon media" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'salon-media');
CREATE POLICY "Owners upload salon media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'salon-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Owners update salon media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'salon-media' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'salon-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Owners delete salon media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'salon-media' AND (storage.foldername(name))[1] = auth.uid()::text);